import{_ as l,c as i,o as e,a2 as o}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"局域网联机（LAN Play）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/finder-sync.md","filePath":"guide/finder-sync.md","lastUpdated":1780466351000}'),t={name:"guide/finder-sync.md"};function r(n,a,s,c,d,p){return e(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="局域网联机-lan-play" tabindex="-1">局域网联机（LAN Play） <a class="header-anchor" href="#局域网联机-lan-play" aria-label="Permalink to &quot;局域网联机（LAN Play）&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>Gomoku 支持在同一局域网内与好友对弈。局域网模式使用本地网络广播发现房间或直接通过地址加入房主。</p><p>主要功能：</p><ul><li>创建房间（Host）并启动局域网服务</li><li>局域网发现（自动列出同一网络的房间）</li><li>直接通过 IP:port 加入指定房间</li><li>房间聊天与观战（如可用）</li></ul><h2 id="如何创建房间-作为主机" tabindex="-1">如何创建房间（作为主机） <a class="header-anchor" href="#如何创建房间-作为主机" aria-label="Permalink to &quot;如何创建房间（作为主机）&quot;">​</a></h2><ol><li>打开 Gomoku，进入 “联机 / 局域网” 页面</li><li>选择“创建房间”或“开始托管”</li><li>选择棋盘尺寸（例如 15x15 / 18x18）和对局规则</li><li>点击“开始托管” — 应显示端口号（默认端口由应用决定）</li><li>通知好友房间名称或你的局域网 IP（示例：192.168.1.42）</li></ol><p>应用会在后台启动一个局域网服务并广播房间信息以便局域网内其他设备发现。</p><h2 id="如何加入房间-作为客户端" tabindex="-1">如何加入房间（作为客户端） <a class="header-anchor" href="#如何加入房间-作为客户端" aria-label="Permalink to &quot;如何加入房间（作为客户端）&quot;">​</a></h2><p>方法一：自动发现</p><ol><li>在“联机 / 局域网”页面选择“查找房间”或刷新列表</li><li>选择显示的房间并点击“加入”</li></ol><p>方法二：手动加入</p><ol><li>选择“手动加入”或“输入地址”</li><li>输入主机的 IP:port（例如 <code>192.168.1.42:12345</code>）</li><li>点击“加入”并等待连接</li></ol><h2 id="权限与网络注意事项-macos" tabindex="-1">权限与网络注意事项（macOS） <a class="header-anchor" href="#权限与网络注意事项-macos" aria-label="Permalink to &quot;权限与网络注意事项（macOS）&quot;">​</a></h2><ul><li>请确保 Gomoku 在 <strong>System Settings → Privacy &amp; Security → Local Network</strong> 中被允许，否则无法被其他设备发现。</li><li>所有设备必须连接到相同的 Wi‑Fi 网络（路由器的 AP 隔离/客户端隔离会阻止发现）。</li><li>如果使用防火墙，请允许 Gomoku 的传入/传出网络流量或打开对应端口。</li></ul><h2 id="常见问题与排查" tabindex="-1">常见问题与排查 <a class="header-anchor" href="#常见问题与排查" aria-label="Permalink to &quot;常见问题与排查&quot;">​</a></h2><ul><li>无法发现房间：检查 Local Network 权限并确保路由没有启用 AP 隔离。</li><li>无法加入（连接超时）：确认主机 IP/端口正确，检查主机防火墙。</li><li>房间出现延迟或卡顿：尝试使用有线连接或更稳定的网络；关闭其它占用带宽的应用。</li></ul><h2 id="日志与持久化" tabindex="-1">日志与持久化 <a class="header-anchor" href="#日志与持久化" aria-label="Permalink to &quot;日志与持久化&quot;">​</a></h2><p>局域网服务的持久化信息（如房间快照）保存在应用的数据目录中。上线后（沙盒环境）路径示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.gomoku/Data/Library/Application Support/com.w3cub.gomoku/</span></span></code></pre></div><p>参考项目文档 <code>docs/macos-sandbox-paths.md</code> 获取更多细节和定位日志的方法。</p><hr><p>如果你希望我把站点上的“联机”指南转换成更详细的步骤（含截图或常见问题模板），我可以继续完善并添加操作截图。</p>',23)])])}const m=l(t,[["render",r]]);export{u as __pageData,m as default};
